// Deterministic request-contract validation. No AI involved.
const body = $json.body || $json;
const errors = [];

const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/;
const KNOWN_PLATFORMS = ['facebook', 'instagram', 'whatsapp'];

if (!body || typeof body !== 'object') errors.push('body_missing');
if (!body.client_id || !UUID_RE.test(String(body.client_id))) errors.push('client_id_invalid');
if (!body.brief || typeof body.brief !== 'string' || body.brief.trim().length < 20) errors.push('brief_too_short');
if (body.brief && body.brief.length > 8000) errors.push('brief_too_long');
if (body.duration_days !== undefined) {
  const d = Number(body.duration_days);
  if (!Number.isFinite(d) || d < 1 || d > 90) errors.push('duration_days_out_of_range');
}
if (body.platforms !== undefined) {
  if (!Array.isArray(body.platforms)) errors.push('platforms_not_array');
  else if (body.platforms.some(p => !KNOWN_PLATFORMS.includes(String(p).toLowerCase()))) errors.push('platforms_unknown_value');
}
for (const k of ['key_messages', 'constraints']) {
  if (body[k] !== undefined && !Array.isArray(body[k])) errors.push(k + '_not_array');
}

// Requested platforms are treated as a REQUEST only. The authoritative allow-list
// is loaded from PostgreSQL later (see 'CODE - Enforce Platform Authorization').
const requested = Array.isArray(body.platforms)
  ? [...new Set(body.platforms.map(p => String(p).toLowerCase()))]
  : [];

return {
  json: {
    valid: errors.length === 0,
    errors,
    received_at: new Date().toISOString(),
    request: {
      client_id: body.client_id || null,
      brief: typeof body.brief === 'string' ? body.brief.trim() : '',
      campaign_objective: body.campaign_objective || null,
      product: body.product || null,
      target_audience: body.target_audience || null,
      requested_platforms: requested,
      tone: body.tone || null,
      duration_days: Number(body.duration_days) || 14,
      key_messages: Array.isArray(body.key_messages) ? body.key_messages : [],
      constraints: Array.isArray(body.constraints) ? body.constraints : []
    }
  }
};

// Merges the authenticated client row with the validated request.
// If no row came back, the client is unauthenticated / inactive.
const req = $('CODE - Validate Request').first().json.request;
const rows = $input.all().map(i => i.json).filter(r => r && r.client_id);

if (rows.length === 0) {
  return [{ json: { authorized: false, reason: 'client_not_found_or_inactive', request: req } }];
}

const c = rows[0];
const allowed = Array.isArray(c.allowed_platforms)
  ? c.allowed_platforms.map(p => String(p).toLowerCase())
  : String(c.allowed_platforms || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);

return [{
  json: {
    authorized: allowed.length > 0,
    reason: allowed.length > 0 ? null : 'no_authorized_platforms',
    request: req,
    client_profile: {
      client_id: c.client_id,
      user_id: c.user_id,
      business_name: c.business_name,
      sector: c.sector,
      description: c.description,
      brand_voice: c.brand_voice,
      audience: c.audience,
      objectives: c.objectives,
      allowed_platforms: allowed
    },
    platform_config: c.platform_config || {}
  }
}];

const base = $('CODE - Build Client Profile').first().json;
const campaign = $input.first().json;
return [{
  json: {
    campaign_id: campaign.campaign_id,
    status: 'processing',
    request: base.request,
    client_profile: base.client_profile,
    platform_config: base.platform_config
  }
}];

// Deterministic schema + grounding validation of the Intent Agent output.
const ctx = $('CODE - Build Campaign Context').first().json;
const raw = $input.first().json;
const errors = [];
let intent = null;

const text = raw?.choices?.[0]?.message?.content;
if (!text) {
  errors.push('no_model_output');
} else {
  try { intent = JSON.parse(String(text).replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); }
  catch (e) { errors.push('invalid_json: ' + e.message); }
}

if (intent) {
  const str = k => typeof intent[k] === 'string' && intent[k].trim().length > 0;
  const arr = k => Array.isArray(intent[k]);
  for (const k of ['campaign_objective', 'product', 'target_audience', 'tone']) if (!str(k)) errors.push('missing_or_empty:' + k);
  for (const k of ['platforms', 'key_messages', 'constraints']) if (!arr(k)) errors.push('not_array:' + k);
  const d = Number(intent.duration_days);
  if (!Number.isFinite(d) || d < 1 || d > 90) errors.push('duration_days_invalid');
  if (arr('key_messages') && intent.key_messages.length === 0) errors.push('key_messages_empty');
  // Grounding: every constraint supplied in the request must survive.
  const supplied = (ctx.request.constraints || []).map(s => String(s).toLowerCase().trim());
  const produced = (arr('constraints') ? intent.constraints : []).map(s => String(s).toLowerCase().trim());
  for (const c of supplied) if (!produced.some(p => p.includes(c) || c.includes(p))) errors.push('constraint_dropped:' + c);
}

// Platform authority: the LLM never decides platforms.
if (intent) intent.platforms = ctx.client_profile.allowed_platforms;

return [{
  json: {
    ...ctx,
    stage: 'intent',
    valid: errors.length === 0,
    validation_errors: errors,
    attempt: 1,
    campaign_intent: intent
  }
}];

const ctx = $('CODE - Build Campaign Context').first().json;
const raw = $input.first().json;
const errors = [];
let intent = null;
const text = raw?.choices?.[0]?.message?.content;
if (!text) errors.push('no_model_output');
else { try { intent = JSON.parse(String(text).replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch (e) { errors.push('invalid_json: ' + e.message); } }
if (intent) {
  const str = k => typeof intent[k] === 'string' && intent[k].trim().length > 0;
  const arr = k => Array.isArray(intent[k]);
  for (const k of ['campaign_objective', 'product', 'target_audience', 'tone']) if (!str(k)) errors.push('missing_or_empty:' + k);
  for (const k of ['platforms', 'key_messages', 'constraints']) if (!arr(k)) errors.push('not_array:' + k);
  const d = Number(intent.duration_days);
  if (!Number.isFinite(d) || d < 1 || d > 90) errors.push('duration_days_invalid');
  intent.platforms = ctx.client_profile.allowed_platforms;
}
return [{ json: { ...ctx, stage: 'intent', valid: errors.length === 0, validation_errors: errors, attempt: 2, campaign_intent: intent } }];

// Carries the validated context into the three parallel research branches.
const src = $('IF - Intent Valid').first().json.valid
  ? $('CODE - Validate Intent').first().json
  : $('CODE - Validate Intent (Retry)').first().json;
return [{ json: src }];

// Observational aggregates only. No causal claims are made or implied.
const rows = $input.all().map(i => i.json).filter(r => r && r.published_at);
const byWeekday = {}, byHour = {}, byPlatform = {};
let total = 0;
for (const r of rows) {
  const d = new Date(r.published_at);
  const score = Number(r.engagement_score) || 0;
  const wd = d.getUTCDay(), hr = d.getUTCHours(), pf = r.platform || 'unknown';
  (byWeekday[wd] = byWeekday[wd] || { n: 0, sum: 0 }).n++; byWeekday[wd].sum += score;
  (byHour[hr] = byHour[hr] || { n: 0, sum: 0 }).n++; byHour[hr].sum += score;
  (byPlatform[pf] = byPlatform[pf] || { n: 0, sum: 0 }).n++; byPlatform[pf].sum += score;
  total += score;
}
const mean = o => Object.fromEntries(Object.entries(o).map(([k, v]) => [k, Number((v.sum / Math.max(v.n, 1)).toFixed(4))]));
const recent = rows.slice(0, 20);
return [{
  json: {
    historical_engagement: {
      observations: rows.length,
      historical_average_engagement_score: rows.length ? Number((total / rows.length).toFixed(4)) : null,
      recent_average_engagement_score: recent.length ? Number((recent.reduce((s, r) => s + (Number(r.engagement_score) || 0), 0) / recent.length).toFixed(4)) : null,
      engagement_by_weekday_utc: mean(byWeekday),
      engagement_by_hour_utc: mean(byHour),
      engagement_by_platform: mean(byPlatform),
      cold_start: rows.length < 30,
      note: 'Observational historical data. No causal relationship between timing and engagement is asserted.'
    },
    raw_history: rows
  }
}];

const ctx = $json;
const i = ctx.campaign_intent || {};
const p = ctx.client_profile || {};
const STOP = new Set(['the','and','for','with','from','that','this','your','our','are','was','have','has','will','into','about','they','their','more','than','then','only','also','very','just','been','over','such']);
const tokens = String([i.product, i.campaign_objective, i.target_audience, p.sector, p.description].filter(Boolean).join(' '))
  .toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/)
  .filter(t => t.length > 3 && !STOP.has(t));
const freq = {};
for (const t of tokens) freq[t] = (freq[t] || 0) + 1;
const keywords = [...new Set([i.product, p.sector].filter(Boolean).map(s => String(s).toLowerCase()))]
  .concat(Object.entries(freq).sort((a, b) => b[1] - a[1]).map(e => e[0]))
  .filter(Boolean).slice(0, 5);
return [{ json: { ...ctx, trend_keywords: keywords } }];

// Reduce raw trend series into three compact features. Google Trends values are
// RELATIVE interest indices, not absolute demand. This is stated to the strategist.
const ctx = $('CODE - Extract Trend Keywords').first().json;
const raw = $input.first().json;
const out = [];

function series(entry) {
  if (Array.isArray(entry?.values)) return entry.values.map(Number).filter(Number.isFinite);
  if (Array.isArray(entry?.timeline)) return entry.timeline.map(p => Number(p.value ?? p[1])).filter(Number.isFinite);
  return [];
}

const entries = Array.isArray(raw?.results) ? raw.results
  : Array.isArray(raw?.data) ? raw.data
  : Array.isArray(raw) ? raw : [];

for (const e of entries) {
  const s = series(e);
  if (s.length < 4) continue;
  const avg = s.reduce((a, b) => a + b, 0) / s.length;
  const tail = s.slice(-Math.max(2, Math.round(s.length * 0.25)));
  const head = s.slice(0, Math.max(2, Math.round(s.length * 0.25)));
  const tailAvg = tail.reduce((a, b) => a + b, 0) / tail.length;
  const headAvg = head.reduce((a, b) => a + b, 0) / head.length;
  const delta = headAvg === 0 ? 0 : (tailAvg - headAvg) / headAvg;
  const sd = Math.sqrt(s.reduce((a, b) => a + Math.pow(b - avg, 2), 0) / s.length);
  out.push({
    keyword: e.keyword || e.query || 'unknown',
    relative_level: avg >= 66 ? 'high' : avg >= 33 ? 'medium' : 'low',
    relative_index: Number(avg.toFixed(1)),
    direction: delta > 0.15 ? 'rising' : delta < -0.15 ? 'falling' : 'stable',
    seasonality: avg > 0 && sd / avg > 0.35 ? 'seasonal' : 'flat'
  });
}

return [{
  json: {
    trend_features: {
      available: out.length > 0,
      source: out.length > 0 ? 'trends_api' : 'unavailable',
      keywords: ctx.trend_keywords,
      signals: out,
      note: 'Google Trends values are relative interest signals, not absolute demand measurements.'
    }
  }
}];

// Only client-nominated competitors, only previously observed public data.
// Nothing is fabricated: absent data is reported as explicitly unavailable.
const rows = $input.all().map(i => i.json).filter(r => r && r.competitor_id);
const observed = rows.filter(r => r.observed_summary);
return [{
  json: {
    competitor_summary: {
      available: observed.length > 0,
      nominated_count: rows.length,
      competitors: observed.map(r => ({
        handle: r.handle,
        platform: r.platform,
        last_observed_at: r.last_observed_at,
        themes: r.observed_summary?.themes || [],
        tone: r.observed_summary?.tone || null,
        posting_cadence: r.observed_summary?.posting_cadence || null,
        content_formats: r.observed_summary?.content_formats || [],
        observable_engagement_patterns: r.observed_summary?.engagement_patterns || null
      })),
      purpose: 'differentiation_only',
      note: observed.length === 0 ? 'No competitor observations available. Do not infer or invent competitor behaviour.' : 'Public observational data only. Use for differentiation, never imitation.'
    }
  }
}];

const ctx = $('CODE - Research Fan Out').first().json;
const hist = $('CODE - Aggregate Engagement History').first().json;
const trends = $('CODE - Process Trend Data').first().json;
const comps = $('CODE - Build Competitor Summary').first().json;
return [{
  json: {
    ...ctx,
    historical_engagement: hist.historical_engagement,
    raw_history: hist.raw_history,
    trend_features: trends.trend_features,
    competitor_summary: comps.competitor_summary
  }
}];

const ctx = $('CODE - Build Research Context').first().json;
const allowed = ctx.client_profile.allowed_platforms;
const raw = $input.first().json;
const errors = [];
let strategy = null;
const text = raw?.choices?.[0]?.message?.content;
if (!text) errors.push('no_model_output');
else { try { strategy = JSON.parse(String(text).replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch (e) { errors.push('invalid_json: ' + e.message); } }

if (strategy) {
  if (!Array.isArray(strategy.themes) || strategy.themes.length === 0) errors.push('themes_invalid');
  if (!Array.isArray(strategy.sequence) || strategy.sequence.length === 0) errors.push('sequence_invalid');
  else {
    strategy.sequence.forEach((s, idx) => {
      if (!Number.isFinite(Number(s.day)) || Number(s.day) < 1 || Number(s.day) > ctx.campaign_intent.duration_days) errors.push('sequence_day_out_of_range:' + idx);
      if (!s.theme || !s.format) errors.push('sequence_missing_fields:' + idx);
      if (!allowed.includes(String(s.platform || '').toLowerCase())) errors.push('sequence_unauthorized_platform:' + idx + ':' + s.platform);
    });
  }
  const sums = (o) => Object.values(o || {}).reduce((a, b) => a + (Number(b) || 0), 0);
  if (typeof strategy.content_mix !== 'object' || Math.abs(sums(strategy.content_mix) - 1) > 0.05) errors.push('content_mix_invalid');
  if (typeof strategy.platform_emphasis !== 'object' || Math.abs(sums(strategy.platform_emphasis) - 1) > 0.05) errors.push('platform_emphasis_invalid');
  for (const p of Object.keys(strategy.platform_emphasis || {})) if (!allowed.includes(String(p).toLowerCase())) errors.push('emphasis_unauthorized_platform:' + p);
  if (typeof strategy.rationale !== 'string' || strategy.rationale.trim().length < 20) errors.push('rationale_invalid');
}

return [{ json: { ...ctx, stage: 'strategy', valid: errors.length === 0, validation_errors: errors, attempt: 1, strategy } }];

const ctx = $('CODE - Build Research Context').first().json;
const allowed = ctx.client_profile.allowed_platforms;
const raw = $input.first().json;
const errors = [];
let strategy = null;
const text = raw?.choices?.[0]?.message?.content;
if (!text) errors.push('no_model_output');
else { try { strategy = JSON.parse(String(text).replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch (e) { errors.push('invalid_json: ' + e.message); } }
if (strategy) {
  if (!Array.isArray(strategy.themes) || strategy.themes.length === 0) errors.push('themes_invalid');
  if (!Array.isArray(strategy.sequence) || strategy.sequence.length === 0) errors.push('sequence_invalid');
  else strategy.sequence.forEach((s, idx) => {
    if (!allowed.includes(String(s.platform || '').toLowerCase())) errors.push('sequence_unauthorized_platform:' + idx);
    if (!s.theme || !s.format) errors.push('sequence_missing_fields:' + idx);
  });
  const sums = o => Object.values(o || {}).reduce((a, b) => a + (Number(b) || 0), 0);
  if (Math.abs(sums(strategy.content_mix) - 1) > 0.05) errors.push('content_mix_invalid');
  if (Math.abs(sums(strategy.platform_emphasis) - 1) > 0.05) errors.push('platform_emphasis_invalid');
  if (typeof strategy.rationale !== 'string' || strategy.rationale.trim().length < 20) errors.push('rationale_invalid');
}
return [{ json: { ...ctx, stage: 'strategy', valid: errors.length === 0, validation_errors: errors, attempt: 2, strategy } }];

// Deterministic expansion of the strategy sequence into content tasks.
// Platform is re-filtered against the authenticated allow-list a second time.
const ctx = $('IF - Strategy Valid').first().json.valid
  ? $('CODE - Validate Strategy').first().json
  : $('CODE - Validate Strategy (Retry)').first().json;
const allowed = new Set(ctx.client_profile.allowed_platforms);
const tasks = [];
let seq = 0;
for (const s of ctx.strategy.sequence) {
  const platform = String(s.platform || '').toLowerCase();
  if (!allowed.has(platform)) continue; // hard drop, never published
  tasks.push({
    task_index: seq++,
    campaign_id: ctx.campaign_id,
    client_id: ctx.client_profile.client_id,
    day: Number(s.day),
    theme: s.theme,
    format: s.format || 'image',
    platform,
    client_profile: ctx.client_profile,
    campaign_intent: ctx.campaign_intent,
    strategy_themes: ctx.strategy.themes,
    content_mix: ctx.strategy.content_mix,
    constraints: ctx.campaign_intent.constraints || []
  });
}
if (tasks.length === 0) throw new Error('No content tasks survived platform authorisation filtering');
return tasks.map(t => ({ json: t }));

// Deterministic creative validation: structure, platform, grounding, constraints.
const task = $('SPLIT - Content Tasks').first().json;
const allowed = new Set(task.client_profile.allowed_platforms);
const raw = $input.first().json;
const errors = [];
let creative = null;

const LIMITS = { facebook: { min: 40, max: 2000, tags: [0, 5] }, instagram: { min: 20, max: 2200, tags: [3, 15] }, whatsapp: { min: 20, max: 900, tags: [0, 0] } };
const BANNED = [/\bcure[sd]?\b/i, /\bguarantee[ds]?\b/i, /\bclinically proven\b/i, /\brisk[- ]free\b/i, /\bFDA[- ]approved\b/i, /\b\d+% (?:more|less|better|faster|guaranteed)\b/i];

const text = raw?.choices?.[0]?.message?.content;
if (!text) errors.push('no_model_output');
else { try { creative = JSON.parse(String(text).replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch (e) { errors.push('invalid_json: ' + e.message); } }

if (creative) {
  const platform = String(creative.platform || '').toLowerCase();
  if (platform !== task.platform) errors.push('platform_mismatch');
  if (!allowed.has(platform)) errors.push('unauthorized_platform');
  if (typeof creative.caption !== 'string' || creative.caption.trim().length === 0) errors.push('caption_missing');
  if (!Array.isArray(creative.hashtags)) errors.push('hashtags_not_array');
  if (typeof creative.format !== 'string' || !creative.format.trim()) errors.push('format_missing');
  if (creative.cta !== undefined && typeof creative.cta !== 'string') errors.push('cta_not_string');

  const lim = LIMITS[task.platform] || LIMITS.facebook;
  const cap = String(creative.caption || '');
  if (cap.length < lim.min) errors.push('caption_too_short');
  if (cap.length > lim.max) errors.push('caption_exceeds_platform_limit');
  if (Array.isArray(creative.hashtags)) {
    if (creative.hashtags.length < lim.tags[0] || creative.hashtags.length > lim.tags[1]) errors.push('hashtag_count_out_of_range');
    if (creative.hashtags.some(h => typeof h !== 'string' || !/^#[A-Za-z0-9_]{2,}$/.test(h))) errors.push('hashtag_format_invalid');
  }
  if (/^\s*[#*>`-]{1,3}\s/m.test(cap) || /\*\*/.test(cap)) errors.push('markdown_detected');

  // Product grounding: the intent product must be traceable in the copy.
  const product = String(task.campaign_intent.product || '').toLowerCase();
  const tokens = product.split(/\s+/).filter(t => t.length > 3);
  if (tokens.length && !tokens.some(t => cap.toLowerCase().includes(t))) errors.push('product_not_grounded');

  // Objective alignment: a promotional/launch objective needs an actionable CTA.
  const obj = String(task.campaign_intent.campaign_objective || '').toLowerCase();
  if (/launch|promo|sale|conversion/.test(obj) && !String(creative.cta || '').trim() && !/\b(shop|order|visit|call|book|dm|message|learn more|sign up)\b/i.test(cap)) errors.push('objective_cta_missing');

  for (const re of BANNED) if (re.test(cap)) errors.push('unsupported_claim:' + re.source);

  // Constraint compliance: negative constraints must not be violated literally.
  for (const c of (task.constraints || [])) {
    const m = String(c).match(/(?:do not|don't|never|avoid|no)\s+(?:mention|use|say|include)?\s*(.+)/i);
    if (m && m[1]) {
      const term = m[1].replace(/[^a-z0-9 ]/gi, ' ').trim().split(/\s+/).filter(w => w.length > 3)[0];
      if (term && cap.toLowerCase().includes(term.toLowerCase())) errors.push('constraint_violated:' + term);
    }
  }
}

return [{ json: { ...task, stage: 'creative_generation', valid: errors.length === 0, validation_errors: errors, attempt: 1, creative } }];

const task = $('SPLIT - Content Tasks').first().json;
const allowed = new Set(task.client_profile.allowed_platforms);
const raw = $input.first().json;
const errors = [];
let creative = null;
const LIMITS = { facebook: { min: 40, max: 2000, tags: [0, 5] }, instagram: { min: 20, max: 2200, tags: [3, 15] }, whatsapp: { min: 20, max: 900, tags: [0, 0] } };
const BANNED = [/\bcure[sd]?\b/i, /\bguarantee[ds]?\b/i, /\bclinically proven\b/i, /\brisk[- ]free\b/i];
const text = raw?.choices?.[0]?.message?.content;
if (!text) errors.push('no_model_output');
else { try { creative = JSON.parse(String(text).replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch (e) { errors.push('invalid_json: ' + e.message); } }
if (creative) {
  const platform = String(creative.platform || '').toLowerCase();
  if (platform !== task.platform) errors.push('platform_mismatch');
  if (!allowed.has(platform)) errors.push('unauthorized_platform');
  const cap = String(creative.caption || '');
  if (!cap.trim()) errors.push('caption_missing');
  if (!Array.isArray(creative.hashtags)) errors.push('hashtags_not_array');
  const lim = LIMITS[task.platform] || LIMITS.facebook;
  if (cap.length < lim.min || cap.length > lim.max) errors.push('caption_length_invalid');
  if (Array.isArray(creative.hashtags) && (creative.hashtags.length < lim.tags[0] || creative.hashtags.length > lim.tags[1])) errors.push('hashtag_count_out_of_range');
  for (const re of BANNED) if (re.test(cap)) errors.push('unsupported_claim');
}
return [{ json: { ...task, stage: 'creative_generation', valid: errors.length === 0, validation_errors: errors, attempt: 2, creative } }];

const ctx = $('IF - Creative Valid').first().json.valid
  ? $('CODE - Validate Creative').first().json
  : $('CODE - Validate Creative (Retry)').first().json;
const raw = $input.first().json;
let p = null;
try { p = JSON.parse(String(raw?.choices?.[0]?.message?.content || '').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch (e) { p = null; }
const ratioDefault = { instagram: '4:5', facebook: '16:9', whatsapp: '1:1' }[ctx.platform] || '1:1';
return [{
  json: {
    ...ctx,
    image_spec: {
      image_prompt: p?.image_prompt || ('Clean, brand-appropriate product photograph for ' + ctx.client_profile.business_name + ' in the ' + ctx.client_profile.sector + ' sector, theme: ' + ctx.theme + '. Natural lighting, uncluttered composition, no text or logos.'),
      negative_prompt: p?.negative_prompt || 'text, watermark, logo, distorted anatomy, low quality',
      aspect_ratio: ['1:1', '4:5', '16:9'].includes(p?.aspect_ratio) ? p.aspect_ratio : ratioDefault,
      style: p?.style || 'photographic',
      prompt_generated: !!p?.image_prompt
    }
  }
}];

// Provider-agnostic normalisation. Image output NEVER influences routing:
// a missing image only downgrades the asset to needs_review.
const ctx = $('CODE - Normalize Image Prompt').first().json;
const asset = $('DB - Create Content Asset').first().json;
const raw = $input.first().json;

let storageRef = null, inlineMime = null, provider = 'gemini';
const parts = raw?.candidates?.[0]?.content?.parts || [];
for (const p of parts) {
  if (p.inlineData?.data) { storageRef = 'inline:' + (p.inlineData.mimeType || 'image/png'); inlineMime = p.inlineData.mimeType; break; }
  if (p.fileData?.fileUri) { storageRef = p.fileData.fileUri; break; }
}
if (!storageRef && typeof raw?.image_url === 'string') { storageRef = raw.image_url; provider = 'custom'; }

const base = ($env.OBJECT_STORAGE_URL || '').replace(/\/$/, '');
const finalRef = storageRef && storageRef.startsWith('inline:') && base
  ? base + '/campaigns/' + ctx.campaign_id + '/' + asset.asset_id + '.png'
  : storageRef;

return [{
  json: {
    ...ctx,
    asset_id: asset.asset_id,
    image: {
      available: !!finalRef,
      storage_ref: finalRef,
      mime_type: inlineMime,
      provider,
      model_version: $env.GEMINI_MODEL || 'gemini-2.5-flash-image'
    },
    approved: !!finalRef,
    review_state: finalRef ? 'approved' : 'needs_review'
  }
}];

/*
 * ENGAGEMENT-INFORMED SCHEDULING (weekday-hour bins, recency weighted)
 * -------------------------------------------------------------------
 * For each bin b (weekday 0-6 x hour 0-23):
 *   E_b     = sum over observations h in b of lambda^age_days(h) * engagement(h)
 *   N_b     = sum over observations h in b of lambda^age_days(h)
 *   Ehat_b  = E_b / max(N_b, 1)
 * Ehat is min-max normalised to [0,1].
 * Shrinkage toward a sector prior:
 *   alpha = min(1, n_total / N_FULL)
 *   W_b   = alpha * Ehat_b + (1 - alpha) * prior_b
 * Assets are then greedily placed in the highest scoring bins that satisfy a
 * minimum spacing constraint; if no bin qualifies the spacing is relaxed
 * progressively. A small jitter is added so posts are not perfectly periodic.
 *
 * IMPORTANT: this is an OBSERVATIONAL heuristic. It selects times that have
 * historically co-occurred with higher engagement. It does NOT establish and
 * must not be described as establishing a causal increase in engagement.
 */
const assets = $input.all().map(i => i.json).filter(a => a && a.asset_id);
if (assets.length === 0) return [];

const ctx = $('CODE - Expand Content Tasks').first().json;
const hist = $('CODE - Aggregate Engagement History').first().json.raw_history || [];
const durationDays = Number($('CODE - Build Research Context').first().json.campaign_intent.duration_days) || 14;

const LAMBDA = 0.97;          // daily recency decay
const N_FULL = 60;            // observations at which client history is fully trusted
const MIN_SPACING_HOURS = 18; // per-platform minimum gap
const JITTER_MIN = 7;         // +/- minutes
const now = new Date();
const key = (wd, hr) => wd + ':' + hr;

// Sector-level prior: business-hours-weighted, used for cold-start clients.
const PRIOR = {};
for (let wd = 0; wd < 7; wd++) for (let hr = 0; hr < 24; hr++) {
  let v = 0.12;
  if (hr >= 7 && hr <= 9) v = 0.70;
  else if (hr >= 11 && hr <= 13) v = 0.80;
  else if (hr >= 17 && hr <= 21) v = 1.00;
  else if (hr >= 14 && hr <= 16) v = 0.55;
  if (wd === 0 || wd === 6) v *= 0.85;
  PRIOR[key(wd, hr)] = v;
}

function binScores(platform) {
  const E = {}, N = {};
  for (const h of hist) {
    if (platform && h.platform && h.platform !== platform) continue;
    const d = new Date(h.published_at);
    if (isNaN(d)) continue;
    const ageDays = Math.max(0, (now - d) / 86400000);
    const w = Math.pow(LAMBDA, ageDays);
    const k = key(d.getUTCDay(), d.getUTCHours());
    E[k] = (E[k] || 0) + w * (Number(h.engagement_score) || 0);
    N[k] = (N[k] || 0) + w;
  }
  const ehat = {};
  for (let wd = 0; wd < 7; wd++) for (let hr = 0; hr < 24; hr++) {
    const k = key(wd, hr);
    ehat[k] = (E[k] || 0) / Math.max(N[k] || 0, 1);
  }
  const vals = Object.values(ehat);
  const mn = Math.min(...vals), mx = Math.max(...vals);
  const span = mx - mn;
  const nObs = hist.filter(h => !platform || !h.platform || h.platform === platform).length;
  const alpha = Math.min(1, nObs / N_FULL);
  const W = {};
  for (const k of Object.keys(ehat)) {
    const norm = span > 0 ? (ehat[k] - mn) / span : 0;
    W[k] = Number((alpha * norm + (1 - alpha) * PRIOR[k]).toFixed(6));
  }
  return { W, alpha, nObs, cold_start: nObs < N_FULL };
}

const placedByPlatform = {};
const out = [];

for (const asset of assets) {
  const platform = asset.platform;
  const { W, alpha, nObs, cold_start } = binScores(platform);
  const day = Math.min(Math.max(Number(asset.planned_day) || 1, 1), durationDays);

  // Candidate timestamps: the planned day, then the two following days.
  const candidates = [];
  for (let offset = 0; offset < 3; offset++) {
    const base = new Date(now.getTime());
    base.setUTCDate(base.getUTCDate() + (day - 1) + offset);
    for (let hr = 0; hr < 24; hr++) {
      const t = new Date(base);
      t.setUTCHours(hr, 0, 0, 0);
      if (t <= now) continue;
      candidates.push({ ts: t, score: W[key(t.getUTCDay(), hr)] || 0, offset });
    }
  }
  candidates.sort((a, b) => (b.score - a.score) || (a.offset - b.offset) || (a.ts - b.ts));

  const placed = placedByPlatform[platform] || (placedByPlatform[platform] = []);
  let chosen = null, spacing = MIN_SPACING_HOURS, relaxed = false;
  while (!chosen && spacing >= 0) {
    chosen = candidates.find(c => placed.every(p => Math.abs(c.ts - p) / 3600000 >= spacing)) || null;
    if (!chosen) { spacing = spacing >= 12 ? 6 : spacing >= 6 ? 2 : -1; relaxed = true; }
  }
  if (!chosen) chosen = candidates[0];
  if (!chosen) continue;

  const jitterMs = Math.round((Math.random() * 2 - 1) * JITTER_MIN) * 60000;
  const scheduledAt = new Date(chosen.ts.getTime() + jitterMs);
  placed.push(scheduledAt);

  out.push({
    json: {
      campaign_id: ctx.campaign_id,
      client_id: ctx.client_id,
      asset_id: asset.asset_id,
      platform,
      scheduled_at: scheduledAt.toISOString(),
      bin_score: Number(chosen.score.toFixed(6)),
      rationale: {
        method: 'recency_weighted_weekday_hour_bins',
        lambda: LAMBDA,
        alpha_client_history_weight: Number(alpha.toFixed(4)),
        observations_used: nObs,
        cold_start_prior_applied: cold_start,
        spacing_hours_applied: Math.max(spacing, 0),
        spacing_relaxed: relaxed,
        jitter_minutes_range: JITTER_MIN,
        selected_bin_utc: { weekday: chosen.ts.getUTCDay(), hour: chosen.ts.getUTCHours() },
        disclaimer: 'Observational selection only. No causal effect on engagement is claimed.'
      }
    }
  });
}

return out;

const ctx = $('CODE - Expand Content Tasks').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.schedule_id);
const now = Date.now();
const out = [];
for (const r of rows) {
  const ts = new Date(r.scheduled_at).getTime();
  if (!Number.isFinite(ts)) continue;          // drop unusable schedule
  if (ts <= now + 60000) continue;             // never schedule in the past
  out.push({ json: { campaign_id: ctx.campaign_id, client_id: ctx.client_id, schedule_id: r.schedule_id, asset_id: r.asset_id, platform: r.platform, scheduled_at: new Date(ts).toISOString() } });
}
if (out.length === 0) throw new Error('No valid schedules produced for campaign ' + ctx.campaign_id);
return out;

// SECURITY GATE. Routing is decided here from the authenticated DB row only.
// No LLM output reaches this decision.
const sched = $('SPLIT - Schedules').first().json;
const row = $input.first().json;

if (!row || !row.schedule_id) {
  return [{ json: { ...sched, route: 'blocked', block_reason: 'schedule_or_client_mismatch' } }];
}

const allowed = Array.isArray(row.allowed_platforms)
  ? row.allowed_platforms.map(p => String(p).toLowerCase())
  : String(row.allowed_platforms || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const platform = String(row.schedule_platform || '').toLowerCase();
const cfg = (row.platform_config || {})[platform] || {};

let route = platform, reason = null;
if (!allowed.includes(platform)) { route = 'blocked'; reason = 'platform_not_authorized_for_client'; }
else if (row.approved !== true || row.review_state !== 'approved') { route = 'blocked'; reason = 'asset_not_approved'; }
else if (Number(row.existing_publications) > 0) { route = 'blocked'; reason = 'already_published_duplicate_prevented'; }
else if (platform === 'whatsapp' && (!cfg.phone_number_id || !cfg.recipients || cfg.recipients.length === 0)) { route = 'blocked'; reason = 'whatsapp_not_configured'; }
else if (platform === 'facebook' && !cfg.page_id) { route = 'blocked'; reason = 'facebook_page_not_configured'; }
else if (platform === 'instagram' && !cfg.ig_user_id) { route = 'blocked'; reason = 'instagram_account_not_configured'; }

return [{
  json: {
    campaign_id: sched.campaign_id,
    client_id: row.client_id,
    schedule_id: row.schedule_id,
    asset_id: row.asset_id,
    platform,
    route,
    block_reason: reason,
    platform_config: cfg,
    creative: row.body,
    storage_ref: row.storage_ref
  }
}];

const sched = $('CODE - Enforce Platform Authorization').first().json;
const r = $input.first().json || {};
return [{
  json: {
    campaign_id: sched.campaign_id,
    client_id: sched.client_id,
    schedule_id: sched.schedule_id,
    asset_id: sched.asset_id,
    platform: sched.platform,
    publication_id: r.publication_id || null,
    platform_post_id: r.platform_post_id || null,
    status: r.status || (sched.route === 'blocked' ? 'blocked' : 'failed'),
    error_detail: r.error_detail || (sched.block_reason ? { stage: 'publication_routing', platform: sched.platform, error_code: sched.block_reason, message: 'Blocked before API call', retry_count: 0, timestamp: new Date().toISOString() } : null),
    published_at: r.published_at || null
  }
}];

const ctx = $('CODE - Final Campaign Report').first().json;
const s = $input.first().json || {};
const pub = Number(s.published_count) || 0;
const fail = Number(s.failed_count) || 0;
const blocked = Number(s.blocked_count) || 0;
const review = Number(s.needs_review_count) || 0;

let status;
if (pub === 0 && (fail > 0 || blocked > 0)) status = 'failed';
else if (pub > 0 && (fail > 0 || blocked > 0)) status = 'partially_published';
else if (pub > 0) status = 'analytics_pending';
else status = 'needs_review';

return [{
  json: {
    campaign_id: ctx.campaign_id,
    client_id: ctx.client_id,
    status,
    report: {
      scheduled: Number(s.scheduled_count) || 0,
      published: pub,
      failed: fail,
      blocked: blocked,
      assets_needing_review: review,
      generated_at: ctx.generated_at,
      note: 'Engagement analytics are collected 24 hours after each successful publication and fed back into historical intelligence.'
    }
  }
}];
